import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import {
  handleOrderIntakeRequest,
  type OnlineOrderCatalogAuthority,
  type OnlineOrderCatalogCategory,
  type OnlineOrderCatalogModifier,
  type OnlineOrderCatalogProduct,
  type OnlineOrderComboBeverageOption,
  type OnlineOrderIntakeStore,
  type OnlineOrderPendingInsert,
  type OnlineOrderProductModifierLink,
  type OnlineOrderStoredRequest,
} from './order-intake.ts';

function record(value: unknown, label: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new Error(`${label} is not an object`);
  }
  return value as Record<string, unknown>;
}

function stringField(value: unknown, label: string): string {
  if (typeof value !== 'string' || value.length === 0) throw new Error(`${label} is invalid`);
  return value;
}

function booleanField(value: unknown, label: string): boolean {
  if (typeof value !== 'boolean') throw new Error(`${label} is invalid`);
  return value;
}

function moneyField(value: unknown, label: string): number {
  const parsed = typeof value === 'number' ? value : Number(value);
  if (!Number.isSafeInteger(parsed) || parsed < 0) throw new Error(`${label} is invalid`);
  return parsed;
}

function nullablePositiveInteger(value: unknown, label: string): number | null {
  if (value === null) return null;
  const parsed = typeof value === 'number' ? value : Number(value);
  if (!Number.isSafeInteger(parsed) || parsed <= 0) throw new Error(`${label} is invalid`);
  return parsed;
}

class SupabaseOnlineOrderIntakeStore implements OnlineOrderIntakeStore {
  constructor(private readonly client: SupabaseClient) {}

  async loadCatalog(shopId: string): Promise<OnlineOrderCatalogAuthority | null> {
    const [shopResult, categoriesResult, productsResult, modifiersResult, linksResult, combosResult] =
      await Promise.all([
        this.client.from('shops').select('id,active').eq('id', shopId).maybeSingle(),
        this.client.from('menu_categories').select('id,shop_id,active').eq('shop_id', shopId),
        this.client
          .from('products')
          .select('id,shop_id,category_id,name,price_minor,active,sold_out,is_combo')
          .eq('shop_id', shopId),
        this.client
          .from('modifiers')
          .select('id,shop_id,name,price_minor,active,standalone_product_id')
          .eq('shop_id', shopId),
        this.client
          .from('product_modifiers')
          .select('product_id,modifier_id,max_quantity')
          .eq('shop_id', shopId),
        this.client
          .from('combo_beverage_options')
          .select('combo_product_id,beverage_product_id')
          .eq('shop_id', shopId),
      ]);

    for (const result of [
      shopResult,
      categoriesResult,
      productsResult,
      modifiersResult,
      linksResult,
      combosResult,
    ]) {
      if (result.error) throw result.error;
    }
    if (!shopResult.data) return null;

    const shop = record(shopResult.data, 'shop');
    const categories: OnlineOrderCatalogCategory[] = (categoriesResult.data ?? []).map((value) => {
      const row = record(value, 'category');
      return {
        id: stringField(row.id, 'category.id'),
        shopId: stringField(row.shop_id, 'category.shop_id'),
        active: booleanField(row.active, 'category.active'),
      };
    });
    const products: OnlineOrderCatalogProduct[] = (productsResult.data ?? []).map((value) => {
      const row = record(value, 'product');
      return {
        id: stringField(row.id, 'product.id'),
        shopId: stringField(row.shop_id, 'product.shop_id'),
        categoryId: stringField(row.category_id, 'product.category_id'),
        name: stringField(row.name, 'product.name'),
        priceMinor: moneyField(row.price_minor, 'product.price_minor'),
        active: booleanField(row.active, 'product.active'),
        soldOut: booleanField(row.sold_out, 'product.sold_out'),
        isCombo: booleanField(row.is_combo, 'product.is_combo'),
      };
    });
    const modifiers: OnlineOrderCatalogModifier[] = (modifiersResult.data ?? []).map((value) => {
      const row = record(value, 'modifier');
      return {
        id: stringField(row.id, 'modifier.id'),
        shopId: stringField(row.shop_id, 'modifier.shop_id'),
        name: stringField(row.name, 'modifier.name'),
        priceMinor: moneyField(row.price_minor, 'modifier.price_minor'),
        active: booleanField(row.active, 'modifier.active'),
        standaloneProductId:
          row.standalone_product_id === null
            ? null
            : stringField(row.standalone_product_id, 'modifier.standalone_product_id'),
      };
    });
    const productModifierLinks: OnlineOrderProductModifierLink[] = (linksResult.data ?? []).map(
      (value) => {
        const row = record(value, 'product modifier link');
        return {
          productId: stringField(row.product_id, 'product modifier link.product_id'),
          modifierId: stringField(row.modifier_id, 'product modifier link.modifier_id'),
          maxQuantity: nullablePositiveInteger(
            row.max_quantity,
            'product modifier link.max_quantity',
          ),
        };
      },
    );
    const comboBeverageOptions: OnlineOrderComboBeverageOption[] = (combosResult.data ?? []).map(
      (value) => {
        const row = record(value, 'combo beverage option');
        return {
          comboProductId: stringField(row.combo_product_id, 'combo beverage option.combo_product_id'),
          beverageProductId: stringField(
            row.beverage_product_id,
            'combo beverage option.beverage_product_id',
          ),
        };
      },
    );

    return {
      shop: {
        id: stringField(shop.id, 'shop.id'),
        active: booleanField(shop.active, 'shop.active'),
      },
      categories,
      products,
      modifiers,
      productModifierLinks,
      comboBeverageOptions,
    };
  }

  async findByIdempotency(
    shopId: string,
    idempotencyKey: string,
  ): Promise<OnlineOrderStoredRequest | null> {
    const { data, error } = await this.client
      .from('online_order_requests')
      .select('id,shop_id,idempotency_key,request_sha256,status')
      .eq('shop_id', shopId)
      .eq('idempotency_key', idempotencyKey)
      .maybeSingle();
    if (error) throw error;
    if (!data) return null;
    const row = record(data, 'online order request');
    const status = stringField(row.status, 'online order request.status');
    if (
      status !== 'PENDING' &&
      status !== 'PROCESSING' &&
      status !== 'ACCEPTED' &&
      status !== 'REJECTED'
    ) {
      throw new Error('online order request status is invalid');
    }
    return {
      id: stringField(row.id, 'online order request.id'),
      shopId: stringField(row.shop_id, 'online order request.shop_id'),
      idempotencyKey: stringField(row.idempotency_key, 'online order request.idempotency_key'),
      requestSha256: stringField(row.request_sha256, 'online order request.request_sha256'),
      status,
    };
  }

  async insertPending(recordToInsert: OnlineOrderPendingInsert): Promise<void> {
    const { error } = await this.client.from('online_order_requests').insert({
      id: recordToInsert.id,
      shop_id: recordToInsert.shopId,
      idempotency_key: recordToInsert.idempotencyKey,
      request_sha256: recordToInsert.requestSha256,
      source_fingerprint: recordToInsert.sourceFingerprint,
      catalog_revision: recordToInsert.catalogRevision,
      status: recordToInsert.status,
      fulfillment_preference: recordToInsert.fulfillmentPreference,
      payment_preference: recordToInsert.paymentPreference,
      customer_name: recordToInsert.customerName,
      normalized_phone: recordToInsert.normalizedPhone,
      delivery_address: recordToInsert.deliveryAddress,
      trusted_items: recordToInsert.trustedItems,
      items_subtotal_minor: recordToInsert.itemsSubtotalMinor,
      order_note: recordToInsert.orderNote,
      accepted_order_id: recordToInsert.acceptedOrderId,
    });
    if (error) throw error;
  }
}

const supabaseUrl = Deno.env.get('SUPABASE_URL');
const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');

if (!supabaseUrl || !serviceRoleKey) {
  console.error('order-intake is missing its trusted Supabase server configuration');
}

const client =
  supabaseUrl && serviceRoleKey
    ? createClient(supabaseUrl, serviceRoleKey, {
        auth: { persistSession: false, autoRefreshToken: false },
      })
    : null;

Deno.serve((request) => {
  if (!client) {
    return new Response(JSON.stringify({ schemaVersion: 1, error: { code: 'intake_not_configured' } }), {
      status: 500,
      headers: {
        'content-type': 'application/json; charset=utf-8',
        'access-control-allow-origin': '*',
      },
    });
  }
  return handleOrderIntakeRequest(request, new SupabaseOnlineOrderIntakeStore(client));
});

import {
  OnlineOrderIntakeContractError,
  parseOnlineOrderRequestV1,
  type OnlineOrderRequestV1,
} from '../../../packages/order-intake-contracts/src/index.ts';
import { normalizeEgyptianPhone } from '../../../packages/domain/src/phone.ts';

const MAX_BODY_BYTES = 64 * 1024;
const INTAKE_CAPACITY_ERROR = 'TUX_ONLINE_ORDER_INTAKE_CAPACITY_EXCEEDED';
const INTAKE_SOURCE_RATE_ERROR = 'TUX_ONLINE_ORDER_INTAKE_SOURCE_RATE_LIMITED';

export interface OnlineOrderCatalogCategory {
  id: string;
  shopId: string;
  active: boolean;
}

export interface OnlineOrderCatalogProduct {
  id: string;
  shopId: string;
  categoryId: string;
  name: string;
  priceMinor: number;
  active: boolean;
  soldOut: boolean;
  isCombo: boolean;
}

export interface OnlineOrderCatalogModifier {
  id: string;
  shopId: string;
  name: string;
  priceMinor: number;
  active: boolean;
  standaloneProductId: string | null;
}

export interface OnlineOrderProductModifierLink {
  productId: string;
  modifierId: string;
  maxQuantity: number | null;
}

export interface OnlineOrderComboBeverageOption {
  comboProductId: string;
  beverageProductId: string;
}

export interface OnlineOrderCatalogAuthority {
  shop: { id: string; active: boolean };
  categories: OnlineOrderCatalogCategory[];
  products: OnlineOrderCatalogProduct[];
  modifiers: OnlineOrderCatalogModifier[];
  productModifierLinks: OnlineOrderProductModifierLink[];
  comboBeverageOptions: OnlineOrderComboBeverageOption[];
}

export interface OnlineOrderStoredRequest {
  id: string;
  shopId: string;
  idempotencyKey: string;
  requestSha256: string;
  status: 'PENDING' | 'PROCESSING' | 'ACCEPTED' | 'REJECTED';
}

export interface OnlineOrderPendingInsert {
  id: string;
  shopId: string;
  idempotencyKey: string;
  requestSha256: string;
  sourceFingerprint: string;
  catalogRevision: string;
  status: 'PENDING';
  fulfillmentPreference: 'DELIVERY' | 'PICKUP';
  paymentPreference: 'CASH' | 'INSTAPAY' | 'MIXED';
  customerName: string;
  normalizedPhone: string | null;
  deliveryAddress: string | null;
  trustedItems: Array<Record<string, unknown>>;
  itemsSubtotalMinor: number;
  orderNote: string | null;
  acceptedOrderId: null;
}

export interface OnlineOrderIntakeStore {
  loadCatalog(shopId: string): Promise<OnlineOrderCatalogAuthority | null>;
  findByIdempotency(
    shopId: string,
    idempotencyKey: string,
  ): Promise<OnlineOrderStoredRequest | null>;
  insertPending(record: OnlineOrderPendingInsert): Promise<void>;
}

function jsonResponse(status: number, body: unknown): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      'content-type': 'application/json; charset=utf-8',
      'access-control-allow-origin': '*',
      'access-control-allow-methods': 'POST, OPTIONS',
      'access-control-allow-headers': 'content-type',
    },
  });
}

function errorResponse(status: number, code: string): Response {
  return jsonResponse(status, { schemaVersion: 1, error: { code } });
}

function successResponse(status: number, requestId: string): Response {
  return jsonResponse(status, { schemaVersion: 1, requestId, status: 'PENDING' });
}

function errorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  if (typeof error === 'object' && error !== null) {
    const message = Reflect.get(error, 'message');
    if (typeof message === 'string') return message;
  }
  return '';
}

function isIntakeRateLimitError(error: unknown): boolean {
  const message = errorMessage(error);
  return message.includes(INTAKE_CAPACITY_ERROR) || message.includes(INTAKE_SOURCE_RATE_ERROR);
}

async function sha256Hex(value: unknown): Promise<string> {
  const bytes = new TextEncoder().encode(JSON.stringify(value));
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('');
}

async function sourceFingerprint(httpRequest: Request): Promise<string> {
  const forwardedFor = httpRequest.headers.get('x-forwarded-for');
  const forwardedChain = (forwardedFor ?? '')
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part.length > 0);
  const gatewayAddress =
    forwardedChain.at(-1) ??
    httpRequest.headers.get('cf-connecting-ip')?.trim() ??
    httpRequest.headers.get('x-real-ip')?.trim() ??
    'gateway-address-unavailable';
  return sha256Hex({ gatewayAddress });
}

function assertTrustedMoney(value: number, label: string): void {
  if (!Number.isSafeInteger(value) || value < 0) {
    throw new Error(`${label} is not a trusted non-negative safe integer`);
  }
}

function canonicalRequest(request: OnlineOrderRequestV1, normalizedPhone: string | null): unknown {
  return {
    schemaVersion: 1,
    shopId: request.shopId,
    idempotencyKey: request.idempotencyKey,
    customer: {
      name: request.customer.name,
      phone: normalizedPhone,
      address: request.customer.address,
    },
    fulfillmentPreference: request.fulfillmentPreference,
    paymentPreference: request.paymentPreference,
    items: request.items.map((item) => ({
      productId: item.productId,
      quantity: item.quantity,
      addonProductIds: [...item.addonProductIds],
      modifierSelections: item.modifierSelections.map((selection) => ({
        modifierId: selection.modifierId,
        quantity: selection.quantity,
      })),
      comboBeverageProductId: item.comboBeverageProductId,
      note: item.note,
    })),
    orderNote: request.orderNote,
  };
}

function canonicalCatalogForRevision(catalog: OnlineOrderCatalogAuthority): unknown {
  const byId = <T extends { id: string }>(rows: T[]): T[] =>
    [...rows].sort((a, b) => a.id.localeCompare(b.id));
  return {
    shop: catalog.shop,
    categories: byId(catalog.categories),
    products: byId(catalog.products),
    modifiers: byId(catalog.modifiers),
    productModifierLinks: [...catalog.productModifierLinks].sort((a, b) =>
      `${a.productId}:${a.modifierId}`.localeCompare(`${b.productId}:${b.modifierId}`),
    ),
    comboBeverageOptions: [...catalog.comboBeverageOptions].sort((a, b) =>
      `${a.comboProductId}:${a.beverageProductId}`.localeCompare(
        `${b.comboProductId}:${b.beverageProductId}`,
      ),
    ),
  };
}

function validateCatalogTenant(catalog: OnlineOrderCatalogAuthority, shopId: string): void {
  if (catalog.shop.id !== shopId || !catalog.shop.active) throw new Error('catalog shop mismatch');
  if (catalog.categories.some((category) => category.shopId !== shopId)) {
    throw new Error('cross-shop category authority');
  }
  if (catalog.products.some((product) => product.shopId !== shopId)) {
    throw new Error('cross-shop product authority');
  }
  if (catalog.modifiers.some((modifier) => modifier.shopId !== shopId)) {
    throw new Error('cross-shop modifier authority');
  }
  const categoryIds = new Set(catalog.categories.map((category) => category.id));
  const productIds = new Set(catalog.products.map((product) => product.id));
  const modifierIds = new Set(catalog.modifiers.map((modifier) => modifier.id));
  if (
    catalog.products.some((product) => !categoryIds.has(product.categoryId)) ||
    catalog.productModifierLinks.some(
      (link) => !productIds.has(link.productId) || !modifierIds.has(link.modifierId),
    ) ||
    catalog.comboBeverageOptions.some(
      (option) => !productIds.has(option.comboProductId) || !productIds.has(option.beverageProductId),
    )
  ) {
    throw new Error('catalog relationship authority mismatch');
  }
}

function buildTrustedItems(
  request: OnlineOrderRequestV1,
  catalog: OnlineOrderCatalogAuthority,
): { trustedItems: Array<Record<string, unknown>>; itemsSubtotalMinor: number } | Response {
  const categories = new Map(catalog.categories.map((category) => [category.id, category]));
  const products = new Map(catalog.products.map((product) => [product.id, product]));
  const modifiers = new Map(catalog.modifiers.map((modifier) => [modifier.id, modifier]));
  const links = new Map(
    catalog.productModifierLinks.map((link) => [`${link.productId}:${link.modifierId}`, link]),
  );
  const comboOptions = new Set(
    catalog.comboBeverageOptions.map(
      (option) => `${option.comboProductId}:${option.beverageProductId}`,
    ),
  );
  const standaloneModifiers = new Map<string, OnlineOrderCatalogModifier>();
  for (const modifier of catalog.modifiers) {
    if (modifier.standaloneProductId !== null) {
      if (standaloneModifiers.has(modifier.standaloneProductId)) {
        throw new Error('ambiguous standalone modifier authority');
      }
      standaloneModifiers.set(modifier.standaloneProductId, modifier);
    }
  }

  const productAvailable = (product: OnlineOrderCatalogProduct | undefined): boolean =>
    product !== undefined &&
    product.active &&
    !product.soldOut &&
    categories.get(product.categoryId)?.active === true;

  let itemsSubtotalMinor = 0;
  const trustedItems: Array<Record<string, unknown>> = [];

  for (const item of request.items) {
    const product = products.get(item.productId);
    if (!productAvailable(product)) {
      return errorResponse(409, 'item_unavailable');
    }
    assertTrustedMoney(product!.priceMinor, 'product price');

    const trustedModifiers: Array<Record<string, unknown>> = [];
    const selectedModifierIds = new Set<string>();
    let modifiersUnitMinor = 0;

    for (const selection of item.modifierSelections) {
      const modifier = modifiers.get(selection.modifierId);
      const link = links.get(`${item.productId}:${selection.modifierId}`);
      if (!modifier || !modifier.active || !link) return errorResponse(400, 'invalid_selection');
      if (
        modifier.standaloneProductId !== null &&
        !productAvailable(products.get(modifier.standaloneProductId))
      ) {
        return errorResponse(409, 'item_unavailable');
      }
      if (link.maxQuantity !== null && selection.quantity > link.maxQuantity) {
        return errorResponse(400, 'invalid_selection');
      }
      if (selectedModifierIds.has(modifier.id)) return errorResponse(400, 'invalid_selection');
      selectedModifierIds.add(modifier.id);
      assertTrustedMoney(modifier.priceMinor, 'modifier price');
      const modifierMinor = modifier.priceMinor * selection.quantity;
      if (!Number.isSafeInteger(modifierMinor)) throw new Error('modifier subtotal overflow');
      modifiersUnitMinor += modifierMinor;
      if (!Number.isSafeInteger(modifiersUnitMinor)) throw new Error('modifier subtotal overflow');
      trustedModifiers.push({
        modifierId: modifier.id,
        label: modifier.name,
        unitPriceMinor: modifier.priceMinor,
        quantity: selection.quantity,
      });
    }

    for (const addonProductId of item.addonProductIds) {
      const addonProduct = products.get(addonProductId);
      if (!productAvailable(addonProduct)) {
        return errorResponse(409, 'item_unavailable');
      }
      const modifier = standaloneModifiers.get(addonProductId);
      if (!modifier || !modifier.active) return errorResponse(400, 'invalid_selection');
      const link = links.get(`${item.productId}:${modifier.id}`);
      if (!link || selectedModifierIds.has(modifier.id)) {
        return errorResponse(400, 'invalid_selection');
      }
      selectedModifierIds.add(modifier.id);
      assertTrustedMoney(modifier.priceMinor, 'addon modifier price');
      modifiersUnitMinor += modifier.priceMinor;
      if (!Number.isSafeInteger(modifiersUnitMinor)) throw new Error('addon subtotal overflow');
      trustedModifiers.push({
        modifierId: modifier.id,
        label: modifier.name,
        unitPriceMinor: modifier.priceMinor,
        quantity: 1,
      });
    }

    let comboBeverage: Record<string, unknown> | null = null;
    if (item.comboBeverageProductId !== null) {
      if (!product!.isCombo) return errorResponse(400, 'invalid_selection');
      const beverage = products.get(item.comboBeverageProductId);
      if (
        !productAvailable(beverage) ||
        !comboOptions.has(`${item.productId}:${item.comboBeverageProductId}`)
      ) {
        return errorResponse(400, 'invalid_selection');
      }
      comboBeverage = { productId: beverage!.id, label: beverage!.name };
    } else if (product!.isCombo) {
      return errorResponse(400, 'invalid_selection');
    }

    const unitConfiguredMinor = product!.priceMinor + modifiersUnitMinor;
    const lineMinor = unitConfiguredMinor * item.quantity;
    if (!Number.isSafeInteger(unitConfiguredMinor) || !Number.isSafeInteger(lineMinor)) {
      throw new Error('line subtotal overflow');
    }
    itemsSubtotalMinor += lineMinor;
    if (!Number.isSafeInteger(itemsSubtotalMinor)) throw new Error('order subtotal overflow');

    trustedItems.push({
      productId: product!.id,
      productName: product!.name,
      unitPriceMinor: product!.priceMinor,
      quantity: item.quantity,
      modifiers: trustedModifiers,
      comboBeverage,
      note: item.note,
    });
  }

  return { trustedItems, itemsSubtotalMinor };
}

export async function handleOrderIntakeRequest(
  httpRequest: Request,
  store: OnlineOrderIntakeStore,
): Promise<Response> {
  if (httpRequest.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'access-control-allow-origin': '*',
        'access-control-allow-methods': 'POST, OPTIONS',
        'access-control-allow-headers': 'content-type',
      },
    });
  }
  if (httpRequest.method !== 'POST') return errorResponse(405, 'method_not_allowed');

  const declaredLength = Number(httpRequest.headers.get('content-length') ?? '0');
  if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
    return errorResponse(413, 'payload_too_large');
  }

  let parsed: OnlineOrderRequestV1;
  try {
    const rawBody = await httpRequest.text();
    if (new TextEncoder().encode(rawBody).byteLength > MAX_BODY_BYTES) {
      return errorResponse(413, 'payload_too_large');
    }
    parsed = parseOnlineOrderRequestV1(JSON.parse(rawBody));
  } catch (error) {
    if (error instanceof OnlineOrderIntakeContractError || error instanceof SyntaxError) {
      return errorResponse(400, 'invalid_request');
    }
    console.error('order-intake request parse failed', error instanceof Error ? error.name : 'Error');
    return errorResponse(500, 'intake_failed');
  }

  let normalizedPhone: string | null = null;
  if (parsed.customer.phone !== null) {
    const phone = normalizeEgyptianPhone(parsed.customer.phone);
    if (!phone.valid) return errorResponse(400, 'invalid_phone');
    normalizedPhone = phone.normalizedPhone;
  }

  const requestSha256 = await sha256Hex(canonicalRequest(parsed, normalizedPhone));
  const requestSourceFingerprint = await sourceFingerprint(httpRequest);
  try {
    const existing = await store.findByIdempotency(parsed.shopId, parsed.idempotencyKey);
    if (existing) {
      if (existing.requestSha256 !== requestSha256) {
        return errorResponse(409, 'idempotency_conflict');
      }
      if (existing.status === 'ACCEPTED') {
        return successResponse(200, existing.id);
      }
      if (existing.status === 'REJECTED') {
        return errorResponse(409, 'request_resolved');
      }
      return successResponse(200, existing.id);
    }

    const catalog = await store.loadCatalog(parsed.shopId);
    if (!catalog || !catalog.shop.active) return errorResponse(404, 'shop_not_found');
    validateCatalogTenant(catalog, parsed.shopId);

    const trusted = buildTrustedItems(parsed, catalog);
    if (trusted instanceof Response) return trusted;
    const catalogRevision = await sha256Hex(canonicalCatalogForRevision(catalog));
    const record: OnlineOrderPendingInsert = {
      id: crypto.randomUUID(),
      shopId: parsed.shopId,
      idempotencyKey: parsed.idempotencyKey,
      requestSha256,
      sourceFingerprint: requestSourceFingerprint,
      catalogRevision,
      status: 'PENDING',
      fulfillmentPreference: parsed.fulfillmentPreference,
      paymentPreference: parsed.paymentPreference,
      customerName: parsed.customer.name,
      normalizedPhone,
      deliveryAddress: parsed.customer.address,
      trustedItems: trusted.trustedItems,
      itemsSubtotalMinor: trusted.itemsSubtotalMinor,
      orderNote: parsed.orderNote,
      acceptedOrderId: null,
    };

    try {
      await store.insertPending(record);
    } catch (error) {
      if (isIntakeRateLimitError(error)) {
        return errorResponse(429, 'intake_rate_limited');
      }
      const raced = await store.findByIdempotency(parsed.shopId, parsed.idempotencyKey);
      if (
        raced?.requestSha256 === requestSha256 &&
        (raced.status === 'PENDING' || raced.status === 'PROCESSING' || raced.status === 'ACCEPTED')
      ) {
        return successResponse(200, raced.id);
      }
      if (raced?.requestSha256 === requestSha256 && raced.status === 'REJECTED') {
        return errorResponse(409, 'request_resolved');
      }
      if (raced) return errorResponse(409, 'idempotency_conflict');
      throw new Error('pending insert failed');
    }
    return successResponse(202, record.id);
  } catch (error) {
    console.error('order-intake failed', error instanceof Error ? error.name : 'Error');
    return errorResponse(500, 'intake_failed');
  }
}

export class OnlineOrderIntakeContractError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'OnlineOrderIntakeContractError';
  }
}

export type OnlineOrderFulfillmentPreferenceV1 = 'DELIVERY' | 'PICKUP';
export type OnlineOrderPaymentPreferenceV1 = 'CASH' | 'INSTAPAY' | 'MIXED';

export interface OnlineOrderModifierSelectionV1 {
  modifierId: string;
  quantity: number;
}

export interface OnlineOrderItemV1 {
  productId: string;
  quantity: number;
  addonProductIds: string[];
  modifierSelections: OnlineOrderModifierSelectionV1[];
  comboBeverageProductId: string | null;
  note: string | null;
}

export interface OnlineOrderCustomerV1 {
  name: string;
  phone: string | null;
  address: string | null;
}

export interface OnlineOrderRequestV1 {
  schemaVersion: 1;
  shopId: string;
  idempotencyKey: string;
  customer: OnlineOrderCustomerV1;
  fulfillmentPreference: OnlineOrderFulfillmentPreferenceV1;
  paymentPreference: OnlineOrderPaymentPreferenceV1;
  items: OnlineOrderItemV1[];
  orderNote: string | null;
}

export interface OnlineOrderIntakeSuccessV1 {
  schemaVersion: 1;
  requestId: string;
  status: 'PENDING';
}

const ROOT_KEYS = [
  'schemaVersion',
  'shopId',
  'idempotencyKey',
  'customer',
  'fulfillmentPreference',
  'paymentPreference',
  'items',
  'orderNote',
] as const;
const CUSTOMER_KEYS = ['name', 'phone', 'address'] as const;
const ITEM_KEYS = [
  'productId',
  'quantity',
  'addonProductIds',
  'modifierSelections',
  'comboBeverageProductId',
  'note',
] as const;
const MODIFIER_KEYS = ['modifierId', 'quantity'] as const;
const SUCCESS_KEYS = ['schemaVersion', 'requestId', 'status'] as const;

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function fail(message: string): never {
  throw new OnlineOrderIntakeContractError(message);
}

function asRecord(value: unknown, path: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    fail(`${path} must be an object`);
  }
  return value as Record<string, unknown>;
}

function assertExactKeys(
  value: Record<string, unknown>,
  allowedKeys: readonly string[],
  path: string,
): void {
  const allowed = new Set(allowedKeys);
  const unexpected = Object.keys(value).filter((key) => !allowed.has(key));
  if (unexpected.length > 0) {
    fail(`${path} contains unexpected field ${unexpected[0]}`);
  }

  for (const key of allowedKeys) {
    if (!Object.prototype.hasOwnProperty.call(value, key)) {
      fail(`${path}.${key} is required`);
    }
  }
}

function asUuid(value: unknown, path: string): string {
  if (typeof value !== 'string' || !UUID_PATTERN.test(value)) {
    fail(`${path} must be a UUID`);
  }
  return value;
}

function asBoundedString(value: unknown, path: string, maxLength: number): string {
  if (typeof value !== 'string') {
    fail(`${path} must be a string`);
  }
  const trimmed = value.trim();
  if (trimmed.length === 0 || value.length > maxLength) {
    fail(`${path} must contain 1-${maxLength} characters`);
  }
  return value;
}

function asNullableBoundedString(value: unknown, path: string, maxLength: number): string | null {
  if (value === null) return null;
  return asBoundedString(value, path, maxLength);
}

function asPositiveInteger(value: unknown, path: string, max: number): number {
  if (!Number.isInteger(value) || typeof value !== 'number' || value < 1 || value > max) {
    fail(`${path} must be an integer between 1 and ${max}`);
  }
  return value;
}

function parseModifierSelection(value: unknown, path: string): OnlineOrderModifierSelectionV1 {
  const record = asRecord(value, path);
  assertExactKeys(record, MODIFIER_KEYS, path);
  return {
    modifierId: asUuid(record.modifierId, `${path}.modifierId`),
    quantity: asPositiveInteger(record.quantity, `${path}.quantity`, 100),
  };
}

function parseItem(value: unknown, path: string): OnlineOrderItemV1 {
  const record = asRecord(value, path);
  assertExactKeys(record, ITEM_KEYS, path);

  if (!Array.isArray(record.addonProductIds) || record.addonProductIds.length > 20) {
    fail(`${path}.addonProductIds must contain at most 20 entries`);
  }
  const addonProductIds = record.addonProductIds.map((entry, index) =>
    asUuid(entry, `${path}.addonProductIds[${index}]`),
  );
  if (new Set(addonProductIds).size !== addonProductIds.length) {
    fail(`${path}.addonProductIds must not contain duplicates`);
  }

  if (!Array.isArray(record.modifierSelections) || record.modifierSelections.length > 20) {
    fail(`${path}.modifierSelections must contain at most 20 entries`);
  }
  const modifierSelections = record.modifierSelections.map((entry, index) =>
    parseModifierSelection(entry, `${path}.modifierSelections[${index}]`),
  );
  const modifierIds = modifierSelections.map((selection) => selection.modifierId);
  if (new Set(modifierIds).size !== modifierIds.length) {
    fail(`${path}.modifierSelections must not contain duplicate modifier IDs`);
  }

  return {
    productId: asUuid(record.productId, `${path}.productId`),
    quantity: asPositiveInteger(record.quantity, `${path}.quantity`, 100),
    addonProductIds,
    modifierSelections,
    comboBeverageProductId:
      record.comboBeverageProductId === null
        ? null
        : asUuid(record.comboBeverageProductId, `${path}.comboBeverageProductId`),
    note: asNullableBoundedString(record.note, `${path}.note`, 500),
  };
}

export function parseOnlineOrderRequestV1(value: unknown): OnlineOrderRequestV1 {
  const record = asRecord(value, 'request');
  assertExactKeys(record, ROOT_KEYS, 'request');

  if (record.schemaVersion !== 1) {
    fail('request.schemaVersion must equal 1');
  }

  const customerRecord = asRecord(record.customer, 'request.customer');
  assertExactKeys(customerRecord, CUSTOMER_KEYS, 'request.customer');

  if (record.fulfillmentPreference !== 'DELIVERY' && record.fulfillmentPreference !== 'PICKUP') {
    fail('request.fulfillmentPreference is unsupported');
  }
  const fulfillmentPreference = record.fulfillmentPreference;

  if (
    record.paymentPreference !== 'CASH' &&
    record.paymentPreference !== 'INSTAPAY' &&
    record.paymentPreference !== 'MIXED'
  ) {
    fail('request.paymentPreference is unsupported');
  }
  const paymentPreference = record.paymentPreference;

  if (!Array.isArray(record.items) || record.items.length < 1 || record.items.length > 50) {
    fail('request.items must contain 1-50 entries');
  }

  const phone = asNullableBoundedString(customerRecord.phone, 'request.customer.phone', 50);
  const address = asNullableBoundedString(customerRecord.address, 'request.customer.address', 500);
  if (fulfillmentPreference === 'DELIVERY' && phone === null) {
    fail('request.customer.phone is required for delivery');
  }
  if (fulfillmentPreference === 'DELIVERY' && address === null) {
    fail('request.customer.address is required for delivery');
  }

  return {
    schemaVersion: 1,
    shopId: asUuid(record.shopId, 'request.shopId'),
    idempotencyKey: asUuid(record.idempotencyKey, 'request.idempotencyKey'),
    customer: {
      name: asBoundedString(customerRecord.name, 'request.customer.name', 200),
      phone,
      address,
    },
    fulfillmentPreference,
    paymentPreference,
    items: record.items.map((entry, index) => parseItem(entry, `request.items[${index}]`)),
    orderNote: asNullableBoundedString(record.orderNote, 'request.orderNote', 1000),
  };
}

export function parseOnlineOrderIntakeSuccessV1(value: unknown): OnlineOrderIntakeSuccessV1 {
  const record = asRecord(value, 'response');
  assertExactKeys(record, SUCCESS_KEYS, 'response');

  if (record.schemaVersion !== 1) {
    fail('response.schemaVersion must equal 1');
  }
  if (record.status !== 'PENDING') {
    fail('response.status must equal PENDING');
  }

  return {
    schemaVersion: 1,
    requestId: asUuid(record.requestId, 'response.requestId'),
    status: 'PENDING',
  };
}

export interface EgyptianPhoneNormalization {
  readonly normalizedPhone: string;
  readonly displayPhone: string;
  readonly valid: boolean;
}

const EGYPTIAN_MOBILE_LOCAL_PATTERN = /^01(?:0|1|2|5)\d{8}$/;
const ALLOWED_PHONE_INPUT_PATTERN = /^\+?[0-9\s()./-]+$/;

function invalidPhone(normalizedPhone: string): EgyptianPhoneNormalization {
  return { normalizedPhone, displayPhone: normalizedPhone, valid: false };
}

/**
 * Normalize the intentionally supported Egyptian mobile forms without ever
 * truncating input. Supported equivalents are:
 *   01xxxxxxxxx
 *   +201xxxxxxxxx
 *   00201xxxxxxxxx
 *   201xxxxxxxxx
 *   1xxxxxxxxx
 * Common spacing and phone punctuation are accepted.
 */
export function normalizeEgyptianPhone(raw: string): EgyptianPhoneNormalization {
  const input = String(raw ?? '').trim();
  if (input.length === 0) return invalidPhone('');
  if (!ALLOWED_PHONE_INPUT_PATTERN.test(input)) return invalidPhone(input);
  if (input.includes('+') && !input.startsWith('+')) return invalidPhone(input);

  const compact = input.replace(/[\s()./-]/g, '');
  let digits: string;
  if (compact.startsWith('+')) {
    if (!compact.startsWith('+20')) return invalidPhone(compact);
    digits = compact.slice(1);
  } else if (compact.startsWith('00')) {
    if (!compact.startsWith('0020')) return invalidPhone(compact);
    digits = compact.slice(2);
  } else {
    digits = compact;
  }

  let normalizedPhone: string;
  if (digits.startsWith('20')) {
    if (digits.length !== 12) return invalidPhone(digits);
    normalizedPhone = `0${digits.slice(2)}`;
  } else if (digits.startsWith('0')) {
    if (digits.length !== 11) return invalidPhone(digits);
    normalizedPhone = digits;
  } else {
    if (digits.length !== 10) return invalidPhone(digits);
    normalizedPhone = `0${digits}`;
  }

  if (!EGYPTIAN_MOBILE_LOCAL_PATTERN.test(normalizedPhone)) {
    return invalidPhone(normalizedPhone);
  }

  return {
    normalizedPhone,
    displayPhone: `+20${normalizedPhone.slice(1)}`,
    valid: true,
  };
}
